import type { JSX } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  /** The message to announce, for example "Habit saved". */
  readonly text: string;
  /** Called when the user dismisses the message. */
  readonly onDismiss: () => void;
}

/**
 * A message shown after something is saved. It is a polite live region, so
 * screen readers announce it when it mounts. It does not take focus, so
 * keyboard users keep their place; the dismiss button is reachable with Tab.
 */
export function StatusMessage({ text, onDismiss }: StatusMessageProps): JSX.Element {
  return (
    <div className="status-message" role="status" aria-live="polite" aria-atomic="true">
      <p className="status-message__text">{text}</p>
      <button type="button" className="status-message__dismiss" onClick={onDismiss}>
        Dismiss
      </button>
    </div>
  );
}
