.status-message {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.6rem 0.9rem;
  border: 1px solid var(--myelin);
  border-radius: 0.75rem;
  background: var(--myelin-wash);
  color: var(--ink);
  font-size: clamp(0.875rem, 0.8rem + 0.3vw, 1rem);
  animation: status-message-in 200ms ease-out;
}

.status-message__text {
  flex: 1;
  min-width: 0;
  margin: 0;
  overflow-wrap: anywhere;
}

.status-message__dismiss {
  flex: none;
  font: inherit;
  color: var(--ink);
  background: transparent;
  border: 1px solid var(--ink);
  border-radius: 999px;
  padding: 0.25rem 0.75rem;
  cursor: pointer;
  transition: background-color 150ms ease;
}

.status-message__dismiss:hover {
  background: var(--cresyl-wash);
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translateY(0.25rem);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

:root[data-motion="reduce"] .status-message,
:root[data-motion="reduce"] .status-message__dismiss {
  animation: none;
  transition: none;
}

@media (prefers-reduced-motion: reduce) {
  .status-message,
  .status-message__dismiss {
    animation: none;
    transition: none;
  }
}
